class LogSanitizerTransform extends Transform {
  constructor() {
    super({ objectMode: false });
  }

  _transform(chunk, encoding, callback) {
    // Strips internal debug stack traces from the stream
    const lines = chunk.toString('utf8').split('\n');
    const sanitized = lines
      .filter((line) => !line.includes('DEBUG:trace:'))
      .join('\n');
