const express = require('express');
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const { pipeline, Transform } = require('stream');
const { ClusterManager } = require('../services/clusterManager');

const app = express();

class LogSanitizerTransform extends Transform {
  constructor() {
    super({ objectMode: false });
  }

  _transform(chunk, encoding, callback) {
    const lines = chunk.toString('utf8').split('\n');
    const sanitized = lines
      .filter((line) => !line.includes('DEBUG:trace:'))
      .join('\n');
    callback(null, Buffer.from(sanitized + '\n'));
  }
}

app.get('/clusters/:clusterId/audit-logs/stream', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate cluster tenancy before opening log stream pipeline
  const cluster = await ClusterManager.findCluster(req.params.clusterId);
  if (!cluster || cluster.tenantId !== req.user.tenantId) {
    return res.status(403).json({ error: 'Access denied to cluster audit logs' });
  }

  const logFile = path.join('/var/logs/clusters', `${req.params.clusterId}.audit.gz`);
  if (!fs.existsSync(logFile)) {
    return res.status(404).json({ error: 'Cluster audit archive not found' });
  }

  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.setHeader('Transfer-Encoding', 'chunked');

  const fileStream = fs.createReadStream(logFile);
  const gunzip = zlib.createGunzip();
  const sanitizer = new LogSanitizerTransform();

  pipeline(fileStream, gunzip, sanitizer, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).json({ error: 'Log streaming pipeline failed' });
    }
  });
});

app.listen(6060);
